        // AR stores time with a granularity of 1 second
        assertEquals(tmp[1].lastModified() / 1000, out.getLastModifiedDate().getTime() / 1000);
        assertFalse(out.isDirectory());
    } finally {
        if (ais != null) {
            ais.close();
        }
