@Test
public void testAvailable() throws Exception {
    final FileInputStream isSz = new FileInputStream(getFile("mixed.txt.sz"));
    try {
        final FramedSnappyCompressorInputStream in = new FramedSnappyCompressorInputStream(isSz);
        // no chunk read so far
        assertEquals(0, in.available());
        assertEquals('1', in.read());
        // remainder of first uncompressed block
        assertEquals(3, in.available());
        assertEquals(3, in.read(new byte[5], 0, 3));
        assertEquals('5', in.read());
        // remainder of literal
        assertEquals(4, in.available());
        assertEquals(4, in.read(new byte[5], 0, 4));
        assertEquals('5', in.read());
        // remainder of copy
        assertEquals(19, in.available());
        in.close();
    } finally {
        isSz.close();
    }
}

